/// <summary>Registers this assembly's generated mediator with the singleton lifetime, and the real-world services.</summary>
public static class MediatorSingletonFanOutSetup
{
    public static IServiceCollection AddMediatorSingletonFanOutBenchmarks(this IServiceCollection services)
    {
        services.AddRealWorldServices();
        // The generator reads these options from this call at compile time.
        return services.AddMediator(
            static (MediatorOptions options) =>
            {
                options.Namespace = "Keryx.Benchmarks.FanOut.MediatorSingleton";
                options.ServiceLifetime = ServiceLifetime.Singleton;
            }
        );
    }
}
